module top_module(
  input clk,
  input reset,
  input data,
  output reg match
);parameter IDLE=2'b00, STATE1=2'b01, STATE2=2'b10;
  reg [1:0] state, next_state;

  always @(posedge clk) begin
    if (reset) begin
      state <= IDLE;
      match <= 0;
    end
    else begin
      state <= next_state;
      match <= (state == STATE2);
    end
  end

  always @(*) begin
    case (state)
      IDLE: begin
        if (data) next_state = STATE1;
        else next_state = IDLE;
      end
      STATE1: begin
        if (data) next_state = STATE2;
        else next_state = IDLE;
      end
      STATE2: begin
        if (data) next_state = STATE2;
        else next_state = STATE1;
      end
    endcase
  end

endmodule

