module debounce(
	input wire clk,
	input wire reset,
	input wire button,
	output reg debounced_button
);reg [15:0] debounce_counter;
	reg button_d;

	always @(posedge clk or posedge reset) begin
		if (reset) begin
			debounce_counter <= 16'b0;
			debounced_button <= 1'b0;
			button_d <= 1'b0;
		end else begin
			button_d <= button;
			if (button != button_d) begin
				debounce_counter <= 16'b0;
