module top_module(
    input clk,
    input reset,
    input in,
    output reg p,  // Change p to reg type
    output reg l
);reg [18:0] r;
    reg [1:0] state;
    parameter IDLE = 2'b00, COUNTING = 2'b01, PULSE = 2'b10;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            r <= 0;
            l <= 0;
            p <= 0;  // Initialize p on reset
            state <= IDLE;
        end else begin
            case(state)
                IDLE: begin
                    if (in) begin
                        state <= COUNTING;
                        r <= 0;
                        l <= 1;
                    end else begin
                        l <= 0;
                    end
                    p <= 0;  // Ensure p is reset to 0
                end
                COUNTING: begin
                    if (r == 250000) begin
                        state <= PULSE;
                        r <= 0;
                        p <= 1;  // Set p to 1
                    end else begin
                        r <= r + 1;
                        l <= 1;
                        p <= 0;  // Set p to 0
                    end
                end
                PULSE: begin
                    if (in) begin
                        state <= COUNTING;
                        r <= 0;
                        p <= 0;  // Set p to 0
                        l <= 1;
                    end else begin
                        l <= 0;
                        p <= 1;  // Set p to 1
                    end
                end
            endcase
        end
    end

endmodule

