code:
module top_module(
    input clk,
    input reset,
    input hold,
    output reg [6:0] q
);

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            // Asynchronous reset: Reset the counter to 7'b0000000
            q <= 7'b0000000;
        end else if (!hold) begin
            // Counter increment: Increment by 1 when not holding
            q <= q + 1;
        end
    end

endmodule

