module mealy_machine (
  input in1,
  input in2,
  input [1:0] state,
  output reg [1:0] next_state,
  output reg out);parameter L=0, M=1, N=2;

    always_comb begin
        case (state)
            L: begin
                next_state = in1 ? M : N;
                out = (in1 && !in2) ? 1 : 0;
            end
            M: begin
                next_state = in2 ? N : L;
                out = (!in1 && in2) ? 1 : 0;
            end
            N: begin
                next_state = (!in1 && !in2) ? L : M;
                out = (in1 && in2) ? 1 : 0;
            end
        endcase
    end

endmodule

