module top_module(
  input clk,
  input reset,
  input data,
  output reg match
);reg [3:0] state, next_state;

parameter S0 = 4'b0000;
parameter S1 = 4'b0001;
parameter S2 = 4'b0010;
parameter S3 = 4'b0011;

always @ (posedge clk or posedge reset) begin
  if (reset) begin
    state <= S0;
    match <= 0;
  end
  else begin
    state <= next_state;
    match <= (state == S3);
  end
end

always @* begin
  case (state)
    S0: begin
      if (data == 1'b1)
        next_state = S1;
      else
        next_state = S0;
    end
    S1: begin
      if (data == 1'b0)
        next_state = S2;
      else
        next_state = S1;
    end
    S2: begin
      if (data == 1'b1)
        next_state = S3;
      else
        next_state = S0;
    end
    S3: begin
      next_state = S0;
    end
    default: next_state = S0;
  endcase
end

endmodule

