		wire[31:0] Rs, Rt;

	integer i;

	reg[31:0] buff[1:31];

	assign Rs = (Rs_Addr==32'd0)?32'd0:buff[Rs_Addr];
	assign Rt = (Rt_Addr==32'd0)?32'd0:buff[Rt_Addr];

	always @(negedge clk or negedge rst)
	begin
