      shift_cnt <= shift_cnt + 1;
      if (shift_cnt == 2'b11) begin
         trig_sr <= datain;
      end
      else begin
         trig_sr <= {trig_sr[2:0], 1'b0};
      end
   end
end

assign trig_done = &shift_cnt;
assign trig_out  = trig_sr[3];

endmodule

