module microwave_oven (
        input clk,
        input areset,
        input start_cooking,
        input stop_cooking,
        output reg cooking);parameter Idle=1'b0, Cooking=1'b1;
	reg state;
	always @(posedge clk or posedge areset) begin
		if (areset)
			state <= Idle;
		else begin
			case (state)
				Idle: state <= start_cooking ? Cooking : Idle;
				Cooking: state <= stop_cooking ? Idle : Cooking;
			endcase
		end
	end

	assign cooking = (state == Cooking);

endmodule

