module register_file
    (
		input clk,
        input rst_n,
        input we,
        input [1:0] wr_addr,
        input [1:0] rd_addr1,
        input [1:0] rd_addr2,
        input [15:0] data_in,
        output reg [15:0] rd_data1,
        output reg [15:0] rd_data2
    );

reg [15:0] regs [0:3];

