module fsm (
    input clk,
    input reset,
    input x,
    output reg y);

    parameter P=0, Q=1, R=2, S=3;
    reg [1:0] state, next;

    always @(posedge clk) begin
        if (reset) state <= P;
        else state <= next;
    end

    always_comb begin
        case (state)
            P: next = x ? Q : P;
            Q: next = x ? Q : R;
            R: next = x ? Q : S;
            S: next = x ? Q : P;
            default: next = 'x;
        endcase
    end

    assign y = (state == S);

endmodule

